Properties GetProperties(uint32_t cp)
{
    if (cp < 0x80) return Properties{ASCII_BITS[cp]};
    if (cp > MAX_CODE_POINT) return Properties{static_cast<uint32_t>(GraphemeBreak::CONTROL)};
    const Run* run = std::upper_bound(std::begin(RUNS), std::end(RUNS), cp, [](uint32_t c, const Run& r) { return c < r.first; }) - 1;
    uint32_t bits = run->bits;
    if ((bits & GRAPHEME_BREAK_MASK) == static_cast<uint32_t>(GraphemeBreak::LV) && (cp - HANGUL_FIRST) % HANGUL_T_COUNT != 0) {
        bits = (bits & ~GRAPHEME_BREAK_MASK) | static_cast<uint32_t>(GraphemeBreak::LVT);
    }
    return Properties{bits};
}

bool IsStandardizedVariant(uint32_t base, uint32_t selector)
{
    return std::binary_search(std::begin(STANDARDIZED_VARIANTS), std::end(STANDARDIZED_VARIANTS), Pair{base, selector});
}

uint32_t SimpleCaseFold(uint32_t cp)
{
    const Pair* found = std::lower_bound(std::begin(CASE_FOLDING), std::end(CASE_FOLDING), Pair{cp, 0});
    return found != std::end(CASE_FOLDING) && found->first == cp ? found->second : cp;
}

